    public static int FrW() {
        // cells of a row
        return 36;
    }
    public static int FrNpred() {
        return 10;
    }
    public static int FrNumber(int row) {
        return FrRows[row * 36 + 0];
    }
    public static int FrBlock(int row) {
        return FrRows[row * 36 + 1];
    }
    public static int FrWinner(int row) {
        return FrRows[row * 36 + 2];
    }
    public static int FrReason(int row) {
        return FrRows[row * 36 + 3];
    }
    public static int FrFlags(int row) {
        return FrRows[row * 36 + 4];
    }
    public static int FrConf(int row) {
        return FrRows[row * 36 + 5];
    }
    public static int FrPcol(int row, int k) {
        return FrRows[row * 36 + (6 + (k * 3))];
    }
    public static int FrPcmp(int row, int k) {
        return FrRows[row * 36 + (7 + (k * 3))];
    }
    public static int FrPset(int row, int k) {
        return FrRows[row * 36 + (8 + (k * 3))];
    }
    public static int FrDefence(int row) {
        // The defence of SPEC 9.5 a row of block 200 is (1-6, by the tens digit of its number minus 19; 24x is the seals', 5), 0 for every other row.
        if (FrBlock(row) != 200) {
            return 0;
        }
        return (FrNumber(row) / 10) - 19;
    }
    public static int FrOrder(int k) {
        // The k-th block a word group is tried against (D224); -1 after the last.
        if (k == 0) {
            return 400;
        }
        if (k == 1) {
            return 600;
        }
        if (k == 2) {
            return 200;
        }
        if (k == 3) {
            return 300;
        }
        if (k == 4) {
            return 100;
        }
        return -1;
    }
    internal static int FrHolds(int row, emon.Port.Cells gv) {
        // 1 when every predicate of `row` holds on the group columns `gv`.
        int k = 0;
        int col = 0;
        int v = 0;
        int s = 0;
        int c = 0;
        while (k < FrNpred()) {
            col = FrPcol(row, k);
            if (col >= 0) {
                v = emon.Port.CellsAt(gv, col);
                s = FrSetting(FrPset(row, k));
                c = FrPcmp(row, k);
                if ((c == FcEq()) && (v != s)) {
                    return 0;
                }
                if ((c == FcNe()) && (v == s)) {
                    return 0;
                }
                if ((c == FcGe()) && ((v < 0) || (v < s))) {
                    return 0;
                }
                if ((c == FcLt()) && ((v < 0) || (v >= s))) {
                    return 0;
                }
            }
            k += 1;
        }
        return 1;
    }
    public static int FrDecide(emon.Port.Cells gv) {
        // The row (an index of `fr-rows`) of the first rule that holds on the group columns `gv`, trying the blocks in `fr-order` and the
        // rows of a block in table order; -1 when none holds (the default row 190 holds for every group, so never in practice).
        int n = 66;
        int b = 0;
        int blk = 0;
        int r = 0;
        while (FrOrder(b) >= 0) {
            blk = FrOrder(b);
            r = 0;
            while (r < n) {
                if (FrBlock(r) == blk) {
                    if (FrHolds(r, gv) == 1) {
                        return r;
                    }
                }
                r += 1;
            }
            b += 1;
        }
        return -1;
    }
    public static int FrDecideBlock(emon.Port.Cells gv, int blk) {
        // The row (an index of `fr-rows`) of the first rule OF BLOCK `blk` that holds on the measures `gv`; -1 when none does. Block 500 reads the graphics
        // measures (`gmz`, codes 100 and up, in a vector of 128 cells), which have a default row (599) so that the answer is never -1 there.
        int n = 66;
        int r = 0;
        while (r < n) {
            if (FrBlock(r) == blk) {
                if (FrHolds(r, gv) == 1) {
                    return r;
                }
            }
            r += 1;
        }
        return -1;
    }
}
